from s114_course_common import teach
S='stereopsis-p1'
teach(S,'depth-cues-1',[
(0,'閉一眼還能猜遠近，靠的是不同線索','深度知覺範圍較廣，雙眼立體視是其中一種機制。',[('Depth perception','知道物體前後或遠近'),('Monocular cues','單眼也能利用的大小、遮擋、陰影等線索'),('Stereopsis','比較左右眼影像的細小位置差，產生立體深度')],'測立體視時要防止用單眼線索猜中，否則不一定測到真正雙眼比較能力。'),
(2,'同樣大的路燈，遠處看起來較小','線索都有假設，不是物體小就一定遠。',[('相對大小','假定實體大小相近時，視像較小常判較遠'),('相對高度／透視','地面上接近地平線、平行線收斂常提示較遠'),('遮擋','擋住別人的物體通常在前')],'照片裁切、不同實物大小或地平線位置都會影響判斷；幾個線索合用更可靠。'),
(4,'轉頭時，窗邊柱子比遠山滑得快','動得快是在說視像，不是柱子真的跑了。',[('動態視差','自己平移時，近景在視野內通常移較快'),('紋理梯度','遠處相似表面細節更小更密'),('陰影／清晰度','依光源、空氣與影像品質等推測形狀或距離')],'「清楚＝近」不是定律；鏡頭對焦遠景時也可近糊遠清。')])
teach(S,'binocular-stereopsis-1',[
(0,'輪流閉眼看手指，相對背景會跳','兩眼位置不同，所以拍到的物體位置略不同。',[('視網膜視差','retinal disparity；左右影像的相對位置差'),('融像fusion','把可相容的兩眼影像合成單一知覺'),('立體視銳度','最小可辨視差，秒角″越小表示越精細')],'視差太大可能複視；也可能抑制一眼，不能只看有沒有抱怨兩個影。'),
(2,'注視點附近，前後也能看成單一個像','horopter不是所有等距離物體組成的一張平面。',[('中央凹','網膜中心最精細視覺區，注視點通常投到這裡'),('Horopter雙眼單視界','落在雙眼對應網膜位置、零視差的空間軌跡'),('Panum融像區','對應位置附近有容許範圍，小視差仍可單視')],'精確形狀隨注視與定義而變；「同一深度的一條線」只能當入門近似，不能代替幾何定義。'),
(4,'固定盯背景時，手指放在背景前方','比較的是物體與注視位置的前後，不是眼球要一直鬥雞眼。',[('交叉crossed','物體比注視位置近，兩眼會需要更會聚才對準它'),('非交叉uncrossed','物體比注視位置遠'),('檢查圖案浮出','常用交叉視差呈現；依測驗設計也可呈現凹入')],'換了注視點，原物體的視差類型也可能改變。')])
teach(S,'disparity-development-1',[
(0,'比兩支筆誰更前面，比單猜一支更穩','相對視差利用物體彼此的差。',[('絕對視差','一物相對雙眼對應位置的視差，與固視有關'),('相對視差','兩物絕對視差之差；有參考物更易比前後'),('注視移動','會改變絕對視差，相對差可較穩定')],'不是兩物一定看得清楚就有精細立體視；仍要兩眼合作。'),
(2,'有很小瞄準誤差，也可能仍看成一個','固視偏差是小誤差，不是已經看到明顯兩個影。',[('Fixation disparity','融像仍維持時的微小眼位誤差'),('Exo外向','集合略不足的方向'),('Eso內向','集合略過度的方向')],'這裡的underconvergence是方向描述，不可直接當正式集合不足CI診斷。'),
(4,'發展年齡與測驗分數，要一起看','實驗室能辨的幾秒角，不等於每份臨床圖冊都有同樣刻度。',[('開始發展','嬰兒約3～5個月可見立體視發展，依研究而異'),('成熟','兒童期持續進步，測法不同可有不同年齡結果'),('測驗差異','可見程度、注意力、矯正與圖冊最細刻度都影響分數')],'保留講義發展年表和5～15秒角參考；不把某一次未過直接當疾病的唯一證據。')])
teach(S,'stereo-tests-1',[
(0,'蒼蠅有輪廓，亂點圖要靠雙眼找形狀','局部／整體是在說如何抽出視差圖案。',[('Local局部','可見輪廓提供對應線索，例如Titmus蒼蠅'),('Global整體','從隨機點的雙眼差找出圖形，例如隨機點圖'),('單眼線索','可能靠輪廓位置或動作猜中，影響測驗效度')],'同一套測驗可能同時有輪廓與隨機點分測驗；不能只靠品牌名概括全部。'),
(2,'測試眼鏡是分圖；處方眼鏡是看清楚','不用特殊分圖眼鏡，不表示可以不戴應戴的矯正鏡。',[('偏光','Titmus、部分Randot等，把兩張圖送到不同眼'),('紅綠','TNO使用顏色濾鏡分圖'),('Frisby／Lang','真實深度板／柱狀透鏡分圖，不需特殊分圖眼鏡')],'依測驗版本距離與姿勢操作；Lang也有離散秒角圖形，不是完全不能給數值。'),
(4,'最後通過的秒角，要連條件記','角秒是空間角度，不是反應花幾秒鐘。',[('1度','60分角＝3600秒角'),('40″與800″','40″能辨更細視差，不是800較好'),('記錄','測驗名稱／版本、距離、矯正、最細可靠通過刻度')],'固定距離圖冊不可任意移近；Frisby設計可用板厚與指定距離換秒角，仍須防單眼移動線索。')])
